=head1 MESSAGES

=head2 Google::Cloud::Dialogflow::V2beta1::Participant::Participant

Represents a conversation participant (human agent, virtual agent, end-user).

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Optional. The unique identifier of this participant.
Format: `projects/<Project ID>/locations/<Location
ID>/conversations/<Conversation ID>/participants/<Participant ID>`.

=item * C<< $msg->role() >> / C<< $msg->role($value) >>

Type: C<Enum> (L<Google::Cloud::Dialogflow::V2beta1::Participant::Role>)

Immutable. The role this participant plays in the conversation. This field
must be set during participant creation and is then immutable.

=item * C<< $msg->obfuscated_external_user_id() >> / C<< $msg->obfuscated_external_user_id($value) >>

Type: C<String>

Optional. Obfuscated user id that should be associated with the created
participant.

You can specify a user id as follows:

1. If you set this field in
   [CreateParticipantRequest][google.cloud.dialogflow.v2beta1.CreateParticipantRequest.participant]
   or
   [UpdateParticipantRequest][google.cloud.dialogflow.v2beta1.UpdateParticipantRequest.participant],
   Dialogflow adds the obfuscated user id with the participant.

2. If you set this field in
   [AnalyzeContent][google.cloud.dialogflow.v2beta1.AnalyzeContentRequest.obfuscated_external_user_id]
   or [StreamingAnalyzeContent]
   [google.cloud.dialogflow.v2beta1.StreamingAnalyzeContentRequest.obfuscated_external_user_id],
   Dialogflow will update
   [Participant.obfuscated_external_user_id][google.cloud.dialogflow.v2beta1.Participant.obfuscated_external_user_id].

Dialogflow uses this user id for billing and measurement. If a user with
the same obfuscated_external_user_id is created in a later conversation,
Dialogflow will know it's the same user.

Dialogflow also uses this user id for Agent Assist suggestion
personalization. For example, Dialogflow can use it to provide personalized
smart reply suggestions for this user.

Additionally, to link an escalated Virtual Agent conversation
with its corresponding Agent Assist conversation for analytics, this field
in Agent Assist conversations should be populated to indicate the user id
of the `END_USER` participant in the escalated conversation.

Note:

* Please never pass raw user ids to Dialogflow. Always obfuscate your user
  id first.
* Dialogflow only accepts a UTF-8 encoded string, e.g., a hex digest of a
  hash function like SHA-512.
* The length of the user id must be <= 256 characters.

=item * C<< $msg->documents_metadata_filters() >> / C<< $msg->documents_metadata_filters($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2beta1::Participant::Participant::DocumentsMetadataFiltersEntry>)

Optional. Key-value filters on the metadata of documents returned by
article suggestion. If specified, article suggestion only returns suggested
documents that match all filters in their
[Document.metadata][google.cloud.dialogflow.v2beta1.Document.metadata].
Multiple values for a metadata key should be concatenated by comma. For
example, filters to match all documents that have 'US' or 'CA' in their
market metadata values and 'agent' in their user metadata values will be
```
documents_metadata_filters {
  key: "market"
  value: "US,CA"
}
documents_metadata_filters {
  key: "user"
  value: "agent"
}
```

=item * C<< $msg->agent_desktop_source() >> / C<< $msg->agent_desktop_source($value) >>

Type: C<Enum> (L<Google::Cloud::Dialogflow::V2beta1::Participant::AgentDesktopSource>)

Optional. For tracking the utilization of prebuilt Agent Assist integration
modules. This field is only inscope for Integration type that include UI
Modules, Backend Modules, and Agent Desktop connector, it is out of scope
for CCaaS and Direct Integration.
For each human agent, prebuilt UI Modules needs to trigger the
UpdateParticipant API to update this field. Both
[CreateParticipantRequest][google.cloud.dialogflow.v2beta1.CreateParticipantRequest.participant]
and
[UpdateParticipantRequest][google.cloud.dialogflow.v2beta1.UpdateParticipantRequest.participant]
will be supported.

=back

