=head2 Google::Cloud::Dialogflow::V2beta1::Participant::AutomatedAgentReply

Represents a response from an automated agent.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->detect_intent_response() >> / C<< $msg->detect_intent_response($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2beta1::Session::DetectIntentResponse>)

Response of the Dialogflow
[Sessions.DetectIntent][google.cloud.dialogflow.v2beta1.Sessions.DetectIntent]
call.

=item * C<< $msg->response_messages() >> / C<< $msg->response_messages($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2beta1::Participant::ResponseMessage>)

Response messages from the automated agent.

=item * C<< $msg->intent() >> / C<< $msg->intent($value) >>

Type: C<String>

Name of the intent if an intent is matched for the query.
For a V2 query, the value format is `projects/<Project ID>/locations/
<Location ID>/agent/intents/<Intent ID>`.
For a V3 query, the value format is `projects/<Project ID>/locations/
<Location ID>/agents/<Agent ID>/intents/<Intent ID>`.

=item * C<< $msg->event() >> / C<< $msg->event($value) >>

Type: C<String>

Event name if an event is triggered for the query.

=item * C<< $msg->match_confidence() >> / C<< $msg->match_confidence($value) >>

Type: C<Float>

The confidence of the match. Values range from 0.0 (completely uncertain)
to 1.0 (completely certain).
This value is for informational purpose only and is only used to help match
the best intent within the classification threshold. This value may change
for the same end-user expression at any time due to a model retraining or
change in implementation.

=item * C<< $msg->parameters() >> / C<< $msg->parameters($value) >>

Type: C<Message> (L<Google::Protobuf::Struct::Struct>)

The collection of current parameters at the time of this response.

=item * C<< $msg->cx_session_parameters() >> / C<< $msg->cx_session_parameters($value) >>

Type: C<Message> (L<Google::Protobuf::Struct::Struct>)

The collection of current Dialogflow CX agent session parameters at the
time of this response.
Deprecated: Use `parameters` instead.

=item * C<< $msg->automated_agent_reply_type() >> / C<< $msg->automated_agent_reply_type($value) >>

Type: C<Enum> (L<Google::Cloud::Dialogflow::V2beta1::AutomatedAgentReply::AutomatedAgentReplyType>)

AutomatedAgentReply type.

=item * C<< $msg->allow_cancellation() >> / C<< $msg->allow_cancellation($value) >>

Type: C<Bool>

Indicates whether the partial automated agent reply is interruptible when a
later reply message arrives. e.g. if the agent specified some music as
partial response, it can be cancelled.

=item * C<< $msg->cx_current_page() >> / C<< $msg->cx_current_page($value) >>

Type: C<String>

The unique identifier of the current Dialogflow CX conversation page.
Format: `projects/<Project ID>/locations/<Location ID>/agents/<Agent
ID>/flows/<Flow ID>/pages/<Page ID>`.

=item * C<< $msg->call_companion_auth_code() >> / C<< $msg->call_companion_auth_code($value) >>

Type: C<Bytes>

The auth code for accessing Call Companion UI.

=back

