The request message for
[Participants.AnalyzeContent][google.cloud.dialogflow.v2beta1.Participants.AnalyzeContent].

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->participant() >> / C<< $msg->participant($value) >>

Type: C<String>

Required. The name of the participant this text comes from.
Format: `projects/<Project ID>/locations/<Location
ID>/conversations/<Conversation ID>/participants/<Participant ID>`.

=item * C<< $msg->text_input() >> / C<< $msg->text_input($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2beta1::Session::TextInput>)

The natural language text to be processed.

=item * C<< $msg->audio_input() >> / C<< $msg->audio_input($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2beta1::Participant::AudioInput>)

The natural language speech audio to be processed.

=item * C<< $msg->event_input() >> / C<< $msg->event_input($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2beta1::Session::EventInput>)

An input event to send to Dialogflow.

=item * C<< $msg->suggestion_input() >> / C<< $msg->suggestion_input($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2beta1::Participant::SuggestionInput>)

An input representing the selection of a suggestion.

=item * C<< $msg->intent_input() >> / C<< $msg->intent_input($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2beta1::Participant::IntentInput>)

The intent to be triggered on V3 agent.

=item * C<< $msg->reply_audio_config() >> / C<< $msg->reply_audio_config($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2beta1::AudioConfig::OutputAudioConfig>)

Speech synthesis configuration.
The speech synthesis settings for a virtual agent that may be configured
for the associated conversation profile are not used when calling
AnalyzeContent. If this configuration is not supplied, speech synthesis
is disabled.

=item * C<< $msg->query_params() >> / C<< $msg->query_params($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2beta1::Session::QueryParameters>)

Parameters for a Dialogflow virtual-agent query.

=item * C<< $msg->assist_query_params() >> / C<< $msg->assist_query_params($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2beta1::Participant::AssistQueryParameters>)

Parameters for a human assist query.

=item * C<< $msg->cx_parameters() >> / C<< $msg->cx_parameters($value) >>

Type: C<Message> (L<Google::Protobuf::Struct::Struct>)

Additional parameters to be put into Dialogflow CX session parameters. To
remove a parameter from the session, clients should explicitly set the
parameter value to null.

Note: this field should only be used if you are connecting to a Dialogflow
CX agent.

=item * C<< $msg->cx_current_page() >> / C<< $msg->cx_current_page($value) >>

Type: C<String>

The unique identifier of the Dialogflow CX page to override the
`current_page` in the session.
Format: `projects/<Project ID>/locations/<Location ID>/agents/<Agent
ID>/flows/<Flow ID>/pages/<Page ID>`.

If `cx_current_page` is specified, the previous state of the session will
be ignored by Dialogflow CX, including the [previous
page][QueryResult.current_page] and the [previous session
parameters][QueryResult.parameters]. In most cases, `cx_current_page` and
`cx_parameters` should be configured together to direct a session to a
specific state.

Note: this field should only be used if you are connecting to a Dialogflow
CX agent.

=item * C<< $msg->message_send_time() >> / C<< $msg->message_send_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Optional. The send time of the message from end user or human agent's
perspective. It is used for identifying the same message under one
participant.

For BatchCreateMessages API only:
Given two messages under the same participant:
* If send time are different regardless of whether the content of the
messages are exactly the same, the conversation will regard them as
two distinct messages sent by the participant.
* If send time is the same regardless of whether the content of the
messages are exactly the same, the conversation will regard them as
same message, and ignore the message received later.

If the value is not provided, a new request will always be regarded as a
new message without any de-duplication.

=item * C<< $msg->request_id() >> / C<< $msg->request_id($value) >>

Type: C<String>

A unique identifier for this request. Restricted to 36 ASCII characters.
A random UUID is recommended.
This request is only idempotent if a `request_id` is provided.

=back

