=over 4

=item * C<< $msg->reply_text() >> / C<< $msg->reply_text($value) >>

Type: C<String>

Output only. The output text content.
This field is set if the automated agent responded with text to show to
the user.

=item * C<< $msg->reply_audio() >> / C<< $msg->reply_audio($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2beta1::Participant::OutputAudio>)

Optional. The audio data bytes encoded as specified in the request.
This field is set if:

 - `reply_audio_config` was specified in the request, or
 - The automated agent responded with audio to play to the user. In such
   case, `reply_audio.config` contains settings used to synthesize the
   speech.

In some scenarios, multiple output audio fields may be present in the
response structure. In these cases, only the top-most-level audio output
has content.

