=head3 Accessors

=over 4

=item * C<< $msg->language_code() >> / C<< $msg->language_code($value) >>

Type: C<String>

Required. The language of this conversational query. See [Language
Support](https://cloud.google.com/dialogflow/docs/reference/language)
for a list of the currently supported language codes.

=back

=head2 Google::Cloud::Dialogflow::V2beta1::Participant::StreamingAnalyzeContentRequest

The top-level message sent by the client to the
[Participants.StreamingAnalyzeContent][google.cloud.dialogflow.v2beta1.Participants.StreamingAnalyzeContent]
method.

Multiple request messages should be sent in order:

1.  The first message must contain
    [participant][google.cloud.dialogflow.v2beta1.StreamingAnalyzeContentRequest.participant],
    [config][google.cloud.dialogflow.v2beta1.StreamingAnalyzeContentRequest.config]
    and optionally
    [query_params][google.cloud.dialogflow.v2beta1.StreamingAnalyzeContentRequest.query_params].
    If you want to receive an audio response, it should also contain
    [reply_audio_config][google.cloud.dialogflow.v2beta1.StreamingAnalyzeContentRequest.reply_audio_config].
    The message must not contain
    [input][google.cloud.dialogflow.v2beta1.StreamingAnalyzeContentRequest.input].

2.  If
[config][google.cloud.dialogflow.v2beta1.StreamingAnalyzeContentRequest.config]
in the first message
    was set to
    [audio_config][google.cloud.dialogflow.v2beta1.StreamingAnalyzeContentRequest.audio_config],
    all subsequent messages must contain
    [input_audio][google.cloud.dialogflow.v2beta1.StreamingAnalyzeContentRequest.input_audio]
    to continue with Speech recognition. If you decide to rather analyze text
    input after you already started Speech recognition, please send a message
    with
    [StreamingAnalyzeContentRequest.input_text][google.cloud.dialogflow.v2beta1.StreamingAnalyzeContentRequest.input_text].

    However, note that:

    * Dialogflow will bill you for the audio so far.
    * Dialogflow discards all Speech recognition results in favor of the
      text input.

 3. If
 [StreamingAnalyzeContentRequest.config][google.cloud.dialogflow.v2beta1.StreamingAnalyzeContentRequest.config]
 in the first message was set
   to
   [StreamingAnalyzeContentRequest.text_config][google.cloud.dialogflow.v2beta1.StreamingAnalyzeContentRequest.text_config],
   then the second message must contain only
   [input_text][google.cloud.dialogflow.v2beta1.StreamingAnalyzeContentRequest.input_text].
   Moreover, you must not send more than two messages.

 After you sent all input, you must half-close or abort the request stream.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->participant() >> / C<< $msg->participant($value) >>

Type: C<String>

Required. The name of the participant this text comes from.
Format: `projects/<Project ID>/locations/<Location
ID>/conversations/<Conversation ID>/participants/<Participant ID>`.

=item * C<< $msg->audio_config() >> / C<< $msg->audio_config($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2beta1::AudioConfig::InputAudioConfig>)

Instructs the speech recognizer how to process the speech audio.

=item * C<< $msg->text_config() >> / C<< $msg->text_config($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2beta1::Participant::InputTextConfig>)

The natural language text to be processed.

=item * C<< $msg->reply_audio_config() >> / C<< $msg->reply_audio_config($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2beta1::AudioConfig::OutputAudioConfig>)

Speech synthesis configuration.
The speech synthesis settings for a virtual agent that may be configured
for the associated conversation profile are not used when calling
StreamingAnalyzeContent. If this configuration is not supplied, speech
synthesis is disabled.

=item * C<< $msg->input_audio() >> / C<< $msg->input_audio($value) >>

Type: C<Bytes>

The input audio content to be recognized. Must be sent if `audio_config`
is set in the first message. The complete audio over all streaming
messages must not exceed 1 minute.

=item * C<< $msg->input_text() >> / C<< $msg->input_text($value) >>

Type: C<String>

The UTF-8 encoded natural language text to be processed. Must be sent if
`text_config` is set in the first message. Text length must not exceed
256 bytes for virtual agent interactions. The `input_text` field can be
only sent once, and would cancel the speech recognition if any ongoing.

=item * C<< $msg->input_dtmf() >> / C<< $msg->input_dtmf($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2beta1::AudioConfig::TelephonyDtmfEvents>)

The DTMF digits used to invoke intent and fill in parameter value.

This input is ignored if the previous response indicated that DTMF input
is not accepted.

=item * C<< $msg->input_intent() >> / C<< $msg->input_intent($value) >>

Type: C<String>

The intent to be triggered on V3 agent.
Format: `projects/<Project ID>/locations/<Location ID>/locations/
<Location ID>/agents/<Agent ID>/intents/<Intent ID>`. This can only be
used to trigger the Welcome intent id if you are using text_config.

=item * C<< $msg->input_event() >> / C<< $msg->input_event($value) >>

Type: C<String>

The input event name.
This can only be sent once and would cancel the ongoing speech
recognition if any. To trigger the Welcome intent use the event "WELCOME"

=item * C<< $msg->suggestion_input() >> / C<< $msg->suggestion_input($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2beta1::Participant::SuggestionInput>)

Optional. Input for confirming, revising, or canceling a suggestion.

=item * C<< $msg->query_params() >> / C<< $msg->query_params($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2beta1::Session::QueryParameters>)

Parameters for a Dialogflow virtual-agent query.

=item * C<< $msg->assist_query_params() >> / C<< $msg->assist_query_params($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2beta1::Participant::AssistQueryParameters>)

Parameters for a human assist query.

=item * C<< $msg->cx_parameters() >> / C<< $msg->cx_parameters($value) >>

Type: C<Message> (L<Google::Protobuf::Struct::Struct>)

Additional parameters to be put into Dialogflow CX session parameters. To
remove a parameter from the session, clients should explicitly set the
parameter value to null.

Note: this field should only be used if you are connecting to a Dialogflow
CX agent.

=item * C<< $msg->cx_current_page() >> / C<< $msg->cx_current_page($value) >>

Type: C<String>

The unique identifier of the Dialogflow CX page to override the
`current_page` in the session.
Format: `projects/<Project ID>/locations/<Location ID>/agents/<Agent
ID>/flows/<Flow ID>/pages/<Page ID>`.

If `cx_current_page` is specified, the previous state of the session will
be ignored by Dialogflow CX, including the [previous
page][QueryResult.current_page] and the [previous session
parameters][QueryResult.parameters]. In most cases, `cx_current_page` and
`cx_parameters` should be configured together to direct a session to a
specific state.

Note: this field should only be used if you are connecting to a Dialogflow
CX agent.

=item * C<< $msg->enable_extended_streaming() >> / C<< $msg->enable_extended_streaming($value) >>

Type: C<Bool>

Optional. Enable full bidirectional streaming. You can keep streaming the
audio until timeout, and there's no need to half close the stream to get
the response.

Restrictions:

- Timeout: 3 mins.
- Audio Encoding: only supports
[AudioEncoding.AUDIO_ENCODING_LINEAR_16][google.cloud.dialogflow.v2beta1.AudioEncoding.AUDIO_ENCODING_LINEAR_16]
and
[AudioEncoding.AUDIO_ENCODING_MULAW][google.cloud.dialogflow.v2beta1.AudioEncoding.AUDIO_ENCODING_MULAW]
- Lifecycle: conversation should be in `Assist Stage`, go to
  [Conversation.CreateConversation][] for more information.

InvalidArgument Error will be returned if the one of restriction checks
failed.

You can find more details in
https://cloud.google.com/agent-assist/docs/extended-streaming

=item * C<< $msg->enable_partial_automated_agent_reply() >> / C<< $msg->enable_partial_automated_agent_reply($value) >>

Type: C<Bool>

Optional. Enable partial responses from Dialogflow CX agent. If this flag
is not enabled, response stream still contains only one final response even
if some `Fulfillment`s in Dialogflow CX agent have been configured to
return partial responses.

=item * C<< $msg->output_multiple_utterances() >> / C<< $msg->output_multiple_utterances($value) >>

Type: C<Bool>

Optional. If multiple utterances are detected in the audio stream, process
them individually instead of stitching them together to form a single
utterance.

=item * C<< $msg->enable_debugging_info() >> / C<< $msg->enable_debugging_info($value) >>

Type: C<Bool>

if true, `StreamingAnalyzeContentResponse.debugging_info` will get
populated.

=back

=head2 Google::Cloud::Dialogflow::V2beta1::Participant::StreamingAnalyzeContentResponse

The top-level message returned from the `StreamingAnalyzeContent` method.

Multiple response messages can be returned in order:

1.  If the input was set to streaming audio, the first one or more messages
    contain `recognition_result`. Each `recognition_result` represents a more
    complete transcript of what the user said. When a user speaks multiple
    sentences, the API will emit multiple messages where `is_final = true`.
    Each time the system detects a distinct pause or completed thought, it
    locks in that segment, marks it `is_final = true`, and then immediately
    starts a new recognition cycle for the next sentence on the same stream.

2.  In virtual agent stage: if `enable_partial_automated_agent_reply` is
    true, the following N (currently 1 <= N <= 4) messages
    contain `automated_agent_reply` and optionally `reply_audio`
    returned by the virtual agent. The first (N-1)
    `automated_agent_reply`s will have `automated_agent_reply_type` set to
    `PARTIAL`. The last `automated_agent_reply` has
    `automated_agent_reply_type` set to `FINAL`.
    If `enable_partial_automated_agent_reply` is not enabled, response stream
    only contains the final reply.

    In human assist stage: the following N (N >= 1) messages contain
    `human_agent_suggestion_results`, `end_user_suggestion_results` or
    `message`.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->recognition_result() >> / C<< $msg->recognition_result($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2beta1::Session::StreamingRecognitionResult>)

The result of speech recognition.

=item * C<< $msg->reply_text() >> / C<< $msg->reply_text($value) >>

Type: C<String>

Optional. The output text content.
This field is set if an automated agent responded with a text for the user.

=item * C<< $msg->reply_audio() >> / C<< $msg->reply_audio($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2beta1::Participant::OutputAudio>)

Optional. The audio data bytes encoded as specified in the request.
This field is set if:

 - The `reply_audio_config` field is specified in the request.
 - The automated agent, which this output comes from, responded with audio.
   In such case, the `reply_audio.config` field contains settings used to
   synthesize the speech.

In some scenarios, multiple output audio fields may be present in the
response structure. In these cases, only the top-most-level audio output
has content.

=item * C<< $msg->automated_agent_reply() >> / C<< $msg->automated_agent_reply($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2beta1::Participant::AutomatedAgentReply>)

Optional. Only set if a Dialogflow automated agent has responded.
Note that: [AutomatedAgentReply.detect_intent_response.output_audio][]
and [AutomatedAgentReply.detect_intent_response.output_audio_config][]
are always empty, use
[reply_audio][google.cloud.dialogflow.v2beta1.StreamingAnalyzeContentResponse.reply_audio]
instead.

=item * C<< $msg->message() >> / C<< $msg->message($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2beta1::Participant::Message>)

Output only. Message analyzed by CCAI.

=item * C<< $msg->human_agent_suggestion_results() >> / C<< $msg->human_agent_suggestion_results($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2beta1::Participant::SuggestionResult>)

The suggestions for most recent human agent. The order is the same as
[HumanAgentAssistantConfig.SuggestionConfig.feature_configs][google.cloud.dialogflow.v2beta1.HumanAgentAssistantConfig.SuggestionConfig.feature_configs]
of
[HumanAgentAssistantConfig.human_agent_suggestion_config][google.cloud.dialogflow.v2beta1.HumanAgentAssistantConfig.human_agent_suggestion_config].

=item * C<< $msg->end_user_suggestion_results() >> / C<< $msg->end_user_suggestion_results($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2beta1::Participant::SuggestionResult>)

The suggestions for end user. The order is the same as
[HumanAgentAssistantConfig.SuggestionConfig.feature_configs][google.cloud.dialogflow.v2beta1.HumanAgentAssistantConfig.SuggestionConfig.feature_configs]
of
[HumanAgentAssistantConfig.end_user_suggestion_config][google.cloud.dialogflow.v2beta1.HumanAgentAssistantConfig.end_user_suggestion_config].

=item * C<< $msg->dtmf_parameters() >> / C<< $msg->dtmf_parameters($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2beta1::Participant::DtmfParameters>)

Indicates the parameters of DTMF.

=item * C<< $msg->debugging_info() >> / C<< $msg->debugging_info($value) >>

Type: C<Message> (L<Google::Cloud::Dialogflow::V2beta1::Session::CloudConversationDebuggingInfo>)

Debugging info that would get populated when
`StreamingAnalyzeContentRequest.enable_debugging_info` is set to true.

=item * C<< $msg->speech_model() >> / C<< $msg->speech_model($value) >>

Type: C<String>

The name of the actual Cloud speech model used for speech recognition.

=back

=head2 Google::Cloud::Dialogflow::V2beta1::Participant::AnnotatedMessagePart

Represents a part of a message possibly annotated with an entity. The part
can be an entity or purely a part of the message between two entities or
message start/end.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->text() >> / C<< $msg->text($value) >>

Type: C<String>

Required. A part of a message possibly annotated with an entity.

=item * C<< $msg->entity_type() >> / C<< $msg->entity_type($value) >>

Type: C<String>

Optional. The [Dialogflow system entity
type](https://cloud.google.com/dialogflow/docs/reference/system-entities)
of this message part. If this is empty, Dialogflow could not annotate the
phrase part with a system entity.

=item * C<< $msg->formatted_value() >> / C<< $msg->formatted_value($value) >>

Type: C<Message> (L<Google::Protobuf::Struct::Value>)

Optional. The [Dialogflow system entity formatted value
](https://cloud.google.com/dialogflow/docs/reference/system-entities) of
this message part. For example for a system entity of type
`@sys.unit-currency`, this may contain:
<pre>
{
  "amount": 5,
  "currency": "USD"
}
</pre>

=back

=head2 Google::Cloud::Dialogflow::V2beta1::Participant::MessageAnnotation

